import React, { useState } from 'react';
import { SideNav, SideNavItems, SideNavMenu, SideNavMenuItem, SideNavLink } from 'carbon-components-react';

function UIShellExample() {
  const [isRailExpanded, setIsRailExpanded] = useState(true);

  const toggleRail = () => {
    setIsRailExpanded(!isRailExpanded);
  };

  return (
    <SideNav
      isRail
      expanded={isRailExpanded}
      onToggle={toggleRail}
      aria-label="Side navigation"
    >
      <SideNavItems>
        <SideNavMenu title="Sub-menu 1">
          <SideNavMenuItem href="#">Menu item 1</SideNavMenuItem>
          <SideNavMenuItem href="#">Menu item 2</SideNavMenuItem>
        </SideNavMenu>
        <SideNavMenu title="Sub-menu 2">
          <SideNavMenuItem href="#">Menu item 3</SideNavMenuItem>
          <SideNavMenuItem href="#">Menu item 4</SideNavMenuItem>
        </SideNavMenu>
        <SideNavLink href="#">Link 1</SideNavLink>
      </SideNavItems>
    </SideNav>
  );
}

export default UIShellExample;
